import csv, json
from collections import defaultdict
from decimal import Decimal, ROUND_HALF_UP
from datetime import date, datetime, time, timedelta
from pathlib import Path

inp = Path('input')
order_date = date(2026, 9, 25)

# Store directory: keep latest effective row on or before the order date.
store_rows = list(csv.DictReader(open(inp / 'store_directory.csv')))
stores = {}
for row in store_rows:
    eff = date.fromisoformat(row['effective_from'])
    sid = row['store_id']
    if sid not in stores or eff > stores[sid]['_eff']:
        row['_eff'] = eff
        stores[sid] = row

catalog = {}
for row in csv.DictReader(open(inp / 'cord_catalogue.csv')):
    catalog[row['sku']] = row

ledger = list(csv.DictReader(open(inp / 'stock_ledger.csv')))

def order_dt_for_store(tz):
    # Buyer ordered at 14:40 Central; Eastern stores are one hour ahead.
    hour = 14 + (1 if tz == 'America/New_York' else 0)
    return datetime(2026, 9, 25, hour, 40)

def effective_stock(store_id, sku, order_dt):
    codes = {sku, catalog[sku]['supplier_part']}
    opening = 0
    adj = 0
    for ln in ledger:
        if ln['store_id'] != store_id or ln['item_code'] not in codes:
            continue
        posted = datetime.fromisoformat(ln['posted_local'])
        event = ln['event']
        qty = int(ln['qty'])
        if event == 'OPENING':
            opening += qty
        elif posted.date() == order_date and posted.time() >= time(9, 0) and posted <= order_dt:
            if event in ('OPENING', 'RECEIPT', 'VOID'):
                adj += qty
            elif event in ('SALE', 'HOLD', 'TRANSFER_OUT'):
                adj -= qty
    return opening + adj

cutoffs = defaultdict(lambda: {'PICKUP': time(15, 0), 'DELIVERY': time(15, 0)})
cutoffs['ST-08']['PICKUP'] = time(16, 0)
paused = {'ST-52': {'DELIVERY'}}

tax = {}
for row in csv.DictReader(open(inp / 'tax_jurisdictions.csv')):
    tax[(row['city'], row['state'])] = Decimal(row['combined_sales_tax_pct'])

def fit_reason(sku):
    c = catalog[sku]
    if c['connector'] != 'C7':
        return 'FIT_CONNECTOR'
    if c['polarized'] == 'Y':
        return 'FIT_POLARIZED'
    length = int(c['length_ft'])
    awg = int(c['conductor_awg'])
    if length > 6 and awg > 18:
        return 'FIT_GAUGE'
    if length < 10 or length > 15:
        return 'FIT_LENGTH'
    return None

def landed_cost(offer):
    price = Decimal(catalog[offer['sku']]['price_usd'])
    if offer['method'] == 'PICKUP':
        tax_pct = Decimal(stores[offer['store_id']]['sales_tax_pct'])
    else:
        tax_pct = tax[('Phenix City', 'AL')]
    taxed = (price * (Decimal('1') + tax_pct / Decimal('100'))).quantize(Decimal('0.01'), ROUND_HALF_UP)
    if offer['method'] == 'DELIVERY':
        return taxed + Decimal('9.99')
    return taxed

offers = list(csv.DictReader(open(inp / 'same_day_offers.csv')))
rows = []
eligible = []

for o in offers:
    store = stores[o['store_id']]
    order_dt = order_dt_for_store(store['timezone'])
    reason = fit_reason(o['sku'])

    if reason is None:
        stock = effective_stock(o['store_id'], o['sku'], order_dt)
        if stock < 1:
            reason = 'NO_STOCK'
        elif o['method'] == 'DELIVERY' and stock < 2:
            reason = 'STOCK_RESERVE'
        elif store['same_day_suspended'] == 'Y' or o['method'] in paused.get(o['store_id'], set()):
            reason = 'SAME_DAY_SUSPENDED'
        elif order_dt.time() >= cutoffs[o['store_id']][o['method']]:
            reason = 'CUTOFF_PASSED'
        elif o['method'] == 'DELIVERY' and Decimal(store['distance_mi']) > Decimal('10'):
            reason = 'OUT_OF_RADIUS'
        else:
            reason = 'NONE'

    if reason == 'NONE':
        cost = landed_cost(o)
        cost_s = f'{cost:.2f}'
        ready = order_dt + timedelta(hours=2) if o['method'] == 'PICKUP' else datetime(2026, 9, 25, 20, 0)
        eligible.append((o, cost, ready, Decimal(store['distance_mi'])))
    else:
        cost_s = ''

    rows.append({
        'offer_id': o['offer_id'],
        'decision': 'ELIGIBLE' if reason == 'NONE' else 'INELIGIBLE',
        'reason_code': reason,
        'landed_cost_usd': cost_s,
    })

with open('offer_evaluation.csv', 'w', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=['offer_id', 'decision', 'reason_code', 'landed_cost_usd'])
    writer.writeheader()
    writer.writerows(rows)

eligible.sort(key=lambda t: (t[1], t[2], t[3], t[0]['offer_id']))
chosen = eligible[0] if eligible else None
results = {
    'eligible_offer_count': len(eligible),
    'chosen_offer_id': chosen[0]['offer_id'] if chosen else '',
    'chosen_total_usd': float(chosen[1]) if chosen else 0,
}

with open('results.json', 'w') as f:
    json.dump(results, f, indent=2)
    f.write('\n')

for r in rows:
    print(f"{r['offer_id']:6} {r['decision']:10} {r['reason_code']:18} {r['landed_cost_usd']}")
print(json.dumps(results, indent=2))
